{"path":"assets/css/styles.css","content":"/* Earthy warm design — system fonts only */
:root{--bg:#FFF8F4;--card:#FFF;--primary:#8B5E3C;--accent:#D9A66B;--muted:#F4EDE6;--text:#2E2A25}
*{box-sizing:border-box}
html,body{height:100%}body{margin:0;font-family:system-ui,-apple-system,'Segoe UI',Roboto,'Helvetica Neue',Arial;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
.container{max-width:1100px;margin:0 auto;padding:32px}
.header-grid{display:flex;align-items:center;justify-content:space-between;padding:12px 0}
.brand{display:flex;gap:12px;align-items:center;text-decoration:none;color:inherit}
.brand-avatar{width:56px;height:56px;border-radius:14px;background:linear-gradient(135deg,var(--muted),#fff);padding:6px}
.brand-name{font-weight:700}
.brand-tag{font-size:13px;color:#6b5b54}
.nav{display:flex;gap:14px;align-items:center}
.nav a{color:var(--text);text-decoration:none;padding:8px}
.nav .btn{border-radius:8px}
.nav-toggle{display:none;border:0;background:transparent;font-size:20px}
.hero{padding-top:36px;padding-bottom:36px}
.hero-inner{display:flex;gap:32px;align-items:center}
.hero-copy{flex:1}
.eyebrow{font-size:14px;color:#6b5b54;margin:0 0 8px}
.hero-title{font-size:30px;margin:0 0 12px}
.lead{color:#4a423d;margin:0 0 18px}
.hero-ctas{display:flex;gap:12px;margin-bottom:16px}
.btn{display:inline-block;padding:10px 16px;border-radius:10px;border:1px solid transparent;background:var(--card);cursor:pointer;text-decoration:none;color:var(--text)}
.btn.primary{background:var(--primary);color:#fff}
.btn.ghost{background:transparent;border-color:rgba(46,42,37,0.06)}
.btn.small{padding:8px 12px;font-size:14px}
.btn.large{padding:14px 20px;font-size:16px}
.lead-form{margin-top:8px}
.lead-form .form-row{display:flex;gap:8px;margin-top:8px}
.lead-form input{flex:1;padding:10px;border-radius:8px;border:1px solid #e8dcd3}
.lead-form .meta{display:block;margin-top:6px;color:#6b5b54;font-size:13px}
.hero-art img{width:320px;height:auto;border-radius:18px;box-shadow:0 8px 24px rgba(139,94,60,0.12)}
.myth-truth{padding:28px 0}
.section-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}
.card{background:var(--card);padding:18px;border-radius:12px;box-shadow:0 4px 18px rgba(46,42,37,0.04)}
.card-contrast{background:linear-gradient(180deg,var(--muted),#fff)}
.pillars{padding:28px 0}
.section-header .kicker{color:#6b5b54;margin-top:6px}
.pillars-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px;margin-top:18px}
.pillar{background:var(--card);padding:18px;border-radius:14px;display:flex;flex-direction:column;gap:12px;align-items:flex-start}
.pillar-visual{width:48px;height:48px}
.case-studies{padding:28px 0}
.cases-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}
.case{background:var(--card);padding:16px;border-radius:12px}
.faq{padding:28px 0}
.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}
.qa{background:var(--card);padding:12px;border-radius:10px}
.q{width:100%;text-align:left;background:transparent;border:0;padding:8px 0;font-weight:600}
.a{display:none;padding-top:6px;color:#4a423d}
.cta{padding:36px 0;background:linear-gradient(90deg,rgba(217,166,107,0.08),transparent)}
.cta-inner{display:flex;justify-content:space-between;align-items:center}
.site-footer{border-top:1px solid rgba(46,42,37,0.04);padding:24px 0;margin-top:36px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.small{color:#6b5b54}
@media (max-width:900px){
  .hero-inner{flex-direction:column}
  .pillars-grid,.cases-grid,.faq-grid{grid-template-columns:1fr}
  .section-grid{grid-template-columns:1fr}
  .nav a.hidden-mobile{display:none}
  .nav-toggle{display:block}
  .nav{gap:8px}
  .cta-inner{flex-direction:column;gap:12px}
}
"} 
{"path":"assets/js/main.js","content":"(function(){
  document.getElementById('year').textContent = new Date().getFullYear();
  // Mobile nav
  var toggle = document.querySelector('.nav-toggle');
  if(toggle){
    toggle.addEventListener('click', function(){
      document.querySelector('.nav').classList.toggle('open');
    });
  }

  // FAQ accordion
  Array.from(document.querySelectorAll('.faq .q')).forEach(function(button){
    button.addEventListener('click', function(){
      var a = this.nextElementSibling;
      var open = a.style.display === 'block';
      // close others
      document.querySelectorAll('.faq .a').forEach(function(el){el.style.display='none'});
      a.style.display = open ? 'none' : 'block';
    });
  });

  // Lead magnet form — simple in-page handling
  var form = document.getElementById('lead-form');
  if(form){
    form.addEventListener('submit', function(e){
      e.preventDefault();
      var email = form.querySelector('input[name="email"]').value;
      if(!email) return alert('Please enter an email');
      // Simulate success
      form.querySelector('.meta').textContent = 'Thanks — check your inbox for the guide.';
      form.reset();
    });
  }

  // Smooth scroll for internal links
  document.querySelectorAll('a[href^="#"]').forEach(function(a){
    a.addEventListener('click', function(e){
      var h = this.getAttribute('href');
      if(h.length>1){
        e.preventDefault();
        var el = document.querySelector(h);
        if(el) el.scrollIntoView({behavior:'smooth',block:'start'});
      }
    });
  });
})();"} 
